From d187790bcea887b63a347c5b63e17514b5195954 Mon Sep 17 00:00:00 2001
From: Rogerio Lucas <rogeriolucas@gmail.com>
Date: Fri, 21 Aug 2026 23:31:49 -0300
Subject: [PATCH 1/5] greeter: start authentication as soon as the lock is
 effective

Arming the authenticators was left to the theme, which has two problems. A theme
that never calls startAuthenticating() leaves the fingerprint authenticator idle,
and no theme can arm anything while its own UI is not being shown, which is
exactly when a fingerprint reader is worth having.

So the greeter arms them itself, at the two moments the lock becomes effective:
when the views are first set up while already locked, and at the end of the grace
period.

That alone is not enough, because an authenticator can do nothing before its
worker process has connected back, and both of those moments come earlier than
that. A request that arrives too early used to be dropped with a warning and
nothing asked again. PamAuthenticators now acts on it once the authenticator
reports itself ready, so whoever asked does not have to poll.
---
 greeter/greeterapp.cpp        | 18 +++++++++++++++++-
 greeter/greeterapp.h          |  1 +
 greeter/pamauthenticators.cpp | 17 +++++++++++++++++
 greeter/pamauthenticators.h   |  1 +
 4 files changed, 36 insertions(+), 1 deletion(-)

diff --git a/greeter/greeterapp.cpp b/greeter/greeterapp.cpp
index ec4283b1..f1eb22d3 100644
--- a/greeter/greeterapp.cpp
+++ b/greeter/greeterapp.cpp
@@ -271,6 +271,18 @@ void UnlockApp::initialViewSetup()
         handleScreen(screen);
     }
     connect(this, &UnlockApp::screenAdded, this, &UnlockApp::handleScreen);
+
+    // Not up to the theme: one that never calls startAuthenticating() leaves the
+    // fingerprint authenticator idle, and a theme cannot be relied on to arm anything
+    // while its own UI is not shown.
+    if (isLocked()) {
+        m_authenticators->startAuthenticating();
+    }
+}
+
+bool UnlockApp::isLocked() const
+{
+    return m_immediateLock || (!m_noLock && !m_delayedLockTimer);
 }

 void UnlockApp::handleScreen(QScreen *screen)
@@ -396,7 +408,7 @@ QQuickView *UnlockApp::createViewForScreen(QScreen *screen)
     }

     QQmlProperty lockProperty(view->rootObject(), QStringLiteral("locked"));
-    lockProperty.write(m_immediateLock || (!m_noLock && !m_delayedLockTimer));
+    lockProperty.write(isLocked());

     // verify that the engine's controller didn't change
     Q_ASSERT(dynamic_cast<NoAccessNetworkAccessManagerFactory *>(view->engine()->networkAccessManagerFactory()));
@@ -477,6 +489,10 @@ void UnlockApp::graceLockEnded()
         QQmlProperty lockProperty(view->rootObject(), QStringLiteral("locked"));
         lockProperty.write(true);
     }
+
+    // The lock only becomes effective now, so this is where authentication starts when the
+    // grace period was in play.
+    m_authenticators->startAuthenticating();
 }

 void UnlockApp::setTesting(bool enable)
diff --git a/greeter/greeterapp.h b/greeter/greeterapp.h
index 84bb1199..9516d8d3 100644
--- a/greeter/greeterapp.h
+++ b/greeter/greeterapp.h
@@ -72,6 +72,7 @@ private:
     void initialize();
     QQuickItem *loadWallpaperPlugin(QObject *parent, int width, int height, KConfigPropertyMap *config);
     void screenGeometryChanged(QScreen *screen, const QRect &geo);
+    bool isLocked() const;
     QWindow *getActiveScreen();

     QString m_packageName;
diff --git a/greeter/pamauthenticators.cpp b/greeter/pamauthenticators.cpp
index e46392c1..b817c7e7 100644
--- a/greeter/pamauthenticators.cpp
+++ b/greeter/pamauthenticators.cpp
@@ -98,6 +98,14 @@ void PamAuthenticators::startAuthenticating()
     setState(AuthenticatorsState::Authenticating);
 }

+void PamAuthenticators::armIfAuthenticating()
+{
+    if (d->state != AuthenticatorsState::Authenticating || d->graceLocked) {
+        return;
+    }
+    startAuthenticating();
+}
+
 void PamAuthenticators::stopAuthenticating()
 {
     qCDebug(KSCREENLOCKER_GREET) << "PamAuthenticators: stopping authenticators";
@@ -137,6 +145,12 @@ void PamAuthenticators::onAuthenticatorChanged()
         d->m_fingerprintAuthenticator.reset();
     } else if (m_authenticator != Authenticator::Fingerprint && !d->m_fingerprintAuthenticator) {
         d->m_fingerprintAuthenticator = std::make_unique<PamAuthenticator>(KSCREENLOCKER_PAM_FINGERPRINT_SERVICE, m_loginName, PamAuthenticator::Fingerprint);
+        connect(d->m_fingerprintAuthenticator.get(), &PamAuthenticator::readyChanged, this, [this] {
+            // An authenticator can do nothing until its worker has connected back, so a
+            // request to start that arrived before that was dropped. Act on it now instead of
+            // waiting for whoever asked to ask again.
+            armIfAuthenticating();
+        });
         connect(d->m_fingerprintAuthenticator.get(), &PamAuthenticator::succeeded, this, [this] {
             qCDebug(KSCREENLOCKER_GREET) << "PamAuthenticators: Success from non-interactive authenticator" << qUtf8Printable(d->m_fingerprintAuthenticator->service());
             saveAuthenticatorType(m_authenticator);
@@ -196,6 +210,9 @@ void PamAuthenticators::onAuthenticatorChanged()
     // Old one got deleted and thus disconnected. Let's connect the new one!

     auto authenticator = d->m_activeAuthenticator.get();
+    connect(authenticator, &PamAuthenticator::readyChanged, this, [this] {
+        armIfAuthenticating();
+    });
     connect(authenticator, &PamAuthenticator::succeeded, this, [this, authenticator] {
         qCDebug(KSCREENLOCKER_GREET) << "PamAuthenticators: Success from interactive authenticator" << qUtf8Printable(authenticator->service());
         saveAuthenticatorType(m_authenticator);
diff --git a/greeter/pamauthenticators.h b/greeter/pamauthenticators.h
index a12105d5..21ef4e0e 100644
--- a/greeter/pamauthenticators.h
+++ b/greeter/pamauthenticators.h
@@ -109,6 +109,7 @@ public:

 private:
     void onAuthenticatorChanged();
+    void armIfAuthenticating();
     Authenticator loadAuthenticatorType();
     void saveAuthenticatorType(Authenticator authenticator);

-- 
