From fea305421e9b95d8692697e88bddc380755367a6 Mon Sep 17 00:00:00 2001
From: Rogerio Lucas <rogeriolucas@gmail.com>
Date: Fri, 21 Aug 2026 23:34:00 -0300
Subject: [PATCH 2/5] greeter: unlock from the greeter, not from the theme

The session was unlocked from the theme, through QQmlEngine::quit. That does not
work when the outputs are away: there is no view to notice the success and ask to
quit, so a fingerprint that authenticated while the screen was off left the
session locked.

The greeter now acts on PamAuthenticators::succeeded itself. It still leaves the
one case the themes handle to them: an active authenticator that succeeded
without ever prompting means no password is set, and themes ask to confirm before
letting that unlock. A finger on a reader needs no confirming, hence the
distinction between succeeding by fingerprint and having been prompted.

isUnlockedByFingerprint() answers the second half of that distinction. The
fingerprint is an implicit authenticator on the side, unless it is itself the active
one, in which case there is no implicit authenticator to ask, so both are checked
and both are guarded against being null.
---
 greeter/greeterapp.cpp        | 32 ++++++++++++++++++++++++--------
 greeter/greeterapp.h          |  1 +
 greeter/pamauthenticators.cpp | 10 ++++++++++
 greeter/pamauthenticators.h   |  2 ++
 4 files changed, 37 insertions(+), 8 deletions(-)

diff --git a/greeter/greeterapp.cpp b/greeter/greeterapp.cpp
index f1eb22d3..3df5a157 100644
--- a/greeter/greeterapp.cpp
+++ b/greeter/greeterapp.cpp
@@ -169,6 +169,16 @@ UnlockApp::UnlockApp(int &argc, char **argv)

     m_authenticators = new PamAuthenticators(KUser().loginName(), this);

+    connect(m_authenticators, &PamAuthenticators::succeeded, this, [this] {
+        // Not up to the theme either: when the outputs are away there is no view to take this
+        // and the session stays locked after a successful authentication. A theme asks to
+        // confirm when the active stack succeeded without ever prompting, because that means
+        // no password is set; a finger on a reader needs no confirming.
+        if (m_authenticators->isUnlockedByFingerprint() || m_authenticators->hadPrompt()) {
+            unlock();
+        }
+    });
+
     auto state = m_engine->singletonInstance<LockscreenState *>("org.kde.kscreenlocker", "LockscreenState");
     state->init(this);

@@ -285,6 +295,19 @@ bool UnlockApp::isLocked() const
     return m_immediateLock || (!m_noLock && !m_delayedLockTimer);
 }

+void UnlockApp::unlock()
+{
+    if (!m_authenticators->isUnlocked()) {
+        qCWarning(KSCREENLOCKER_GREET) << "Greeter tried to quit without being unlocked";
+        return;
+    }
+
+    qCDebug(KSCREENLOCKER_GREET) << "Unlocked";
+    // Mind that we can quit properly. All the blocking PAM tech is in subprocesses that will get reaped either
+    // by destructors or by themselves once they notice we are gone.
+    qApp->quit();
+}
+
 void UnlockApp::handleScreen(QScreen *screen)
 {
     if (screen->geometry().isNull()) {
@@ -327,14 +350,7 @@ QQuickView *UnlockApp::createViewForScreen(QScreen *screen)
     QQmlContext *context = view->engine()->rootContext();
     connect(view->engine(), &QQmlEngine::quit, this, [this]() {
         qCDebug(KSCREENLOCKER_GREET) << "Greeter quit signal received, checking if we are unlocked";
-        if (m_authenticators->isUnlocked()) {
-            qCDebug(KSCREENLOCKER_GREET) << "Unlocked";
-            // Mind that we can quit properly. All the blocking PAM tech is in subprocesses that will get reaped either
-            // by destructors or by themselves once they notice we are gone.
-            qApp->quit();
-        } else {
-            qCWarning(KSCREENLOCKER_GREET) << "Greeter tried to quit without being unlocked";
-        }
+        unlock();
     });

     context->setContextProperty(QStringLiteral("kscreenlocker_userName"), m_userName);
diff --git a/greeter/greeterapp.h b/greeter/greeterapp.h
index 9516d8d3..5278dee1 100644
--- a/greeter/greeterapp.h
+++ b/greeter/greeterapp.h
@@ -73,6 +73,7 @@ private:
     QQuickItem *loadWallpaperPlugin(QObject *parent, int width, int height, KConfigPropertyMap *config);
     void screenGeometryChanged(QScreen *screen, const QRect &geo);
     bool isLocked() const;
+    void unlock();
     QWindow *getActiveScreen();

     QString m_packageName;
diff --git a/greeter/pamauthenticators.cpp b/greeter/pamauthenticators.cpp
index b817c7e7..5765a776 100644
--- a/greeter/pamauthenticators.cpp
+++ b/greeter/pamauthenticators.cpp
@@ -76,6 +76,16 @@ bool PamAuthenticators::isUnlocked() const
     return !d->locked;
 }

+bool PamAuthenticators::isUnlockedByFingerprint() const
+{
+    if (d->m_fingerprintAuthenticator && d->m_fingerprintAuthenticator->isUnlocked()) {
+        return true;
+    }
+    // The fingerprint can also be the active authenticator, and then the implicit one above
+    // does not exist at all.
+    return m_authenticator == Authenticator::Fingerprint && d->m_activeAuthenticator && d->m_activeAuthenticator->isUnlocked();
+}
+
 PamAuthenticators::AuthenticatorsState PamAuthenticators::state() const
 {
     return d->state;
diff --git a/greeter/pamauthenticators.h b/greeter/pamauthenticators.h
index 21ef4e0e..46b038a2 100644
--- a/greeter/pamauthenticators.h
+++ b/greeter/pamauthenticators.h
@@ -91,6 +91,8 @@ public:

     // this property is true if any of the authenticators' unlocked properties are true
     bool isUnlocked() const;
+    // and this one only if it was a fingerprint that unlocked, which needs no confirming
+    [[nodiscard]] bool isUnlockedByFingerprint() const;
     Q_SIGNAL void succeeded();

     PamAuthenticator::NoninteractiveAuthenticatorTypes authenticatorTypes() const;
-- 
