From 991d9eef00c8ef46272c90e944eebacc7db5928d Mon Sep 17 00:00:00 2001
From: Rogerio Lucas <rogeriolucas@gmail.com>
Date: Fri, 21 Aug 2026 23:47:06 -0300
Subject: [PATCH 3/5] greeter: do not ask to confirm a smartcard or a token
 either

The check the previous commit put in the greeter asked whether a fingerprint had
unlocked, which is the shape the pre-rework code had, where the fingerprint was
the noninteractive stack. It is not the shape this one has: a smartcard, a face or
a u2f token is an active authenticator now, so a smartcard verifying without a
prompt landed in the same bucket as a password stack that never prompted, and sat
there waiting for a theme to confirm it.

State the condition the way it was meant instead of enumerating what may unlock:
confirmation is for the password stack succeeding without ever asking for a
password, because that is what an account with no password looks like. Anything
else that succeeded was a deliberate act by somebody standing at the machine.

This also keeps the bug 497904 shape working, since a fingerprint success with no
prompt does not match the confirmation case.
---
 greeter/greeterapp.cpp        | 9 ++++-----
 greeter/pamauthenticators.cpp | 9 +++++++++
 greeter/pamauthenticators.h   | 9 +++++++--
 3 files changed, 20 insertions(+), 7 deletions(-)

diff --git a/greeter/greeterapp.cpp b/greeter/greeterapp.cpp
index 3df5a157..04c44680 100644
--- a/greeter/greeterapp.cpp
+++ b/greeter/greeterapp.cpp
@@ -170,11 +170,10 @@ UnlockApp::UnlockApp(int &argc, char **argv)
     m_authenticators = new PamAuthenticators(KUser().loginName(), this);

     connect(m_authenticators, &PamAuthenticators::succeeded, this, [this] {
-        // Not up to the theme either: when the outputs are away there is no view to take this
-        // and the session stays locked after a successful authentication. A theme asks to
-        // confirm when the active stack succeeded without ever prompting, because that means
-        // no password is set; a finger on a reader needs no confirming.
-        if (m_authenticators->isUnlockedByFingerprint() || m_authenticators->hadPrompt()) {
+        // Not up to the theme either, there is no view to take this while the outputs are
+        // gone. The one case that does stay with the themes is a success the user has to
+        // confirm.
+        if (!m_authenticators->needsUnlockConfirmation()) {
             unlock();
         }
     });
diff --git a/greeter/pamauthenticators.cpp b/greeter/pamauthenticators.cpp
index 5765a776..678ac859 100644
--- a/greeter/pamauthenticators.cpp
+++ b/greeter/pamauthenticators.cpp
@@ -86,6 +86,15 @@ bool PamAuthenticators::isUnlockedByFingerprint() const
     return m_authenticator == Authenticator::Fingerprint && d->m_activeAuthenticator && d->m_activeAuthenticator->isUnlocked();
 }

+bool PamAuthenticators::needsUnlockConfirmation() const
+{
+    // Themes ask the user to confirm when the password stack succeeded without ever asking
+    // for a password, because that is what an account with no password looks like. Anything
+    // else that succeeded - a finger, a smartcard, a token - was a deliberate act by
+    // somebody standing at the machine and needs no confirming.
+    return m_authenticator == Authenticator::Regular && !hadPrompt() && !isUnlockedByFingerprint();
+}
+
 PamAuthenticators::AuthenticatorsState PamAuthenticators::state() const
 {
     return d->state;
diff --git a/greeter/pamauthenticators.h b/greeter/pamauthenticators.h
index 46b038a2..793af490 100644
--- a/greeter/pamauthenticators.h
+++ b/greeter/pamauthenticators.h
@@ -91,8 +91,12 @@ public:

     // this property is true if any of the authenticators' unlocked properties are true
     bool isUnlocked() const;
-    // and this one only if it was a fingerprint that unlocked, which needs no confirming
-    [[nodiscard]] bool isUnlockedByFingerprint() const;
+    /*!
+        Whether a success has to be confirmed by the user before it may unlock. Only true for
+        the one case that belongs to the themes: the password stack succeeding without ever
+        prompting, which means the account has no password.
+     */
+    [[nodiscard]] bool needsUnlockConfirmation() const;
     Q_SIGNAL void succeeded();

     PamAuthenticator::NoninteractiveAuthenticatorTypes authenticatorTypes() const;
@@ -112,6 +116,7 @@ public:
 private:
     void onAuthenticatorChanged();
     void armIfAuthenticating();
+    [[nodiscard]] bool isUnlockedByFingerprint() const;
     Authenticator loadAuthenticatorType();
     void saveAuthenticatorType(Authenticator authenticator);

-- 
