From 14e31c604f70d87f786940772ebb5a9305cf8680 Mon Sep 17 00:00:00 2001
From: jf nz <talon_usable_9k@icloud.com>
Date: Mon, 31 Aug 2026 14:40:37 +1200
Subject: [PATCH 4/5] autotests: cover authentication start before worker
 readiness

---
 autotests/CMakeLists.txt |  2 ++
 autotests/pamtest.cpp    | 24 ++++++++++++++++++++++++
 2 files changed, 26 insertions(+)

diff --git a/autotests/CMakeLists.txt b/autotests/CMakeLists.txt
index d7138eef..5a3df0e6 100644
--- a/autotests/CMakeLists.txt
+++ b/autotests/CMakeLists.txt
@@ -23,6 +23,8 @@ pkg_search_module(PamWrapper REQUIRED pam_wrapper>=1.1.6)
 pkg_get_variable(PamWrapperModuleDir pam_wrapper "modules")
 # We use a different target dir so we can QFINDTESTDATA the two dirs separately
 configure_file(data/test_service.in services/test_service)
+configure_file(data/test_service.in services/${KSCREENLOCKER_PAM_PASSWORD_SERVICE})
+configure_file(data/test_service.in services/${KSCREENLOCKER_PAM_FINGERPRINT_SERVICE})
 add_executable(pamTest pamtest.cpp)
 target_link_libraries(pamTest Qt::Test kscreenlocker_authenticator)
 add_test(NAME ksmserver-pamTest COMMAND pamTest)
diff --git a/autotests/pamtest.cpp b/autotests/pamtest.cpp
index a3f7cc11..634ad196 100644
--- a/autotests/pamtest.cpp
+++ b/autotests/pamtest.cpp
@@ -8,6 +8,7 @@ SPDX-License-Identifier: GPL-2.0-or-later
 #include <QTest>

 #include "../greeter/pamauthenticator.h"
+#include "../greeter/pamauthenticators.h"

 // This test runs under the expectation that
 // we are run with LD_PRELOAD=libpam_wrapper.so pamTest
@@ -19,6 +20,7 @@ public:
     PamTest();
 private Q_SLOTS:
     void testLogin();
+    void testStartBeforeReady();
 };

 PamTest::PamTest()
@@ -68,5 +70,27 @@ void PamTest::testLogin()
     QVERIFY(busyChangedSpy.count() == 4);
 }

+void PamTest::testStartBeforeReady()
+{
+    PamAuthenticators authenticators(QStringLiteral("test_user"));
+    QSignalSpy succeededSpy(&authenticators, &PamAuthenticators::succeeded);
+    QSignalSpy failedSpy(&authenticators, &PamAuthenticators::failed);
+    int promptCount = 0;
+    connect(&authenticators, &PamAuthenticators::promptForSecretChanged, this, [&] {
+        if (!authenticators.promptForSecret().isEmpty()) {
+            ++promptCount;
+        }
+    });
+
+    authenticators.startAuthenticating();
+
+    QTRY_COMPARE(promptCount, 1);
+    authenticators.respond("my_password");
+    QVERIFY(succeededSpy.wait());
+    QCOMPARE(promptCount, 1);
+    QCOMPARE(succeededSpy.count(), 1);
+    QCOMPARE(failedSpy.count(), 0);
+}
+
 QTEST_MAIN(PamTest)
 #include "pamtest.moc"
-- 
