From e238a746c1f78bda00dd6326e27498b49c7856c9 Mon Sep 17 00:00:00 2001
From: jf nz <talon_usable_9k@icloud.com>
Date: Sat, 5 Sep 2026 12:15:09 -0300
Subject: [PATCH 5/5] autotests: give pamTest its own configuration and state
 directories

PamAuthenticators reads the selected authenticator when it is constructed
and writes it back on success. So the readiness test ran against whatever
the developer had selected, which cannot work for the ones with no service
fixture, and rewrote the real config afterwards.
---
 autotests/pamtest.cpp | 13 +++++++++++++
 1 file changed, 13 insertions(+)

diff --git a/autotests/pamtest.cpp b/autotests/pamtest.cpp
index 634ad196..2ee22ec5 100644
--- a/autotests/pamtest.cpp
+++ b/autotests/pamtest.cpp
@@ -5,6 +5,7 @@ SPDX-License-Identifier: GPL-2.0-or-later
 */

 #include <QSignalSpy>
+#include <QTemporaryDir>
 #include <QTest>

 #include "../greeter/pamauthenticator.h"
@@ -21,6 +22,9 @@ public:
 private Q_SLOTS:
     void testLogin();
     void testStartBeforeReady();
+
+private:
+    QTemporaryDir m_testDir;
 };

 PamTest::PamTest()
@@ -29,6 +33,14 @@ PamTest::PamTest()
         qFatal("This test must be run with pam_wrapper. See ctest");
     }

+    if (!m_testDir.isValid()) {
+        qFatal("Could not create temporary configuration directory");
+    }
+    // PamAuthenticators reads the selected authenticator and saves it on success.
+    qputenv("XDG_CONFIG_HOME", m_testDir.filePath(QStringLiteral("config")).toUtf8());
+    qputenv("XDG_CONFIG_DIRS", m_testDir.filePath(QStringLiteral("config")).toUtf8());
+    qputenv("XDG_STATE_HOME", m_testDir.filePath(QStringLiteral("state")).toUtf8());
+
     qputenv("PAM_WRAPPER", "1");
     qputenv("PAM_WRAPPER_DEBUGLEVEL", "2"); // DEBUG level
     qputenv("PAM_WRAPPER_SERVICE_DIR", QFINDTESTDATA("services").toUtf8());
@@ -73,6 +85,7 @@ void PamTest::testLogin()
 void PamTest::testStartBeforeReady()
 {
     PamAuthenticators authenticators(QStringLiteral("test_user"));
+    QCOMPARE(authenticators.property("authenticator").value<PamAuthenticators::Authenticator>(), PamAuthenticators::Authenticator::Regular);
     QSignalSpy succeededSpy(&authenticators, &PamAuthenticators::succeeded);
     QSignalSpy failedSpy(&authenticators, &PamAuthenticators::failed);
     int promptCount = 0;
